package org.sleepwell.app;
import android.os.SystemClock;import org.junit.Test;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
public final class TrackingDelayStorageTest {
 @Test public void dueClaimCreatesOnlyActualCaptureRowAndCannotReplay()throws Exception{try(TrackingDelayFixture f=new TrackingDelayFixture()){long elapsed=600000,wall=System.currentTimeMillis();TrackingDelay plan=new TrackingDelay("due",elapsed-300000,wall-300000,1,5,false,false,false,false,TrackingDelay.Phase.WAITING,0,"");TrackingDelayRuntime.Job j=f.job();j.arm(plan,null,null);f.idle();try(Store s=new Store(f.c,f.database)){assertTrue(s.rows("SELECT * FROM sessions").isEmpty());assertTrue(s.rows("SELECT * FROM epochs").isEmpty());}AtomicInteger effects=new AtomicInteger();AtomicLong id=new AtomicLong();CountDownLatch first=new CountDownLatch(1);j.claim("due",elapsed,1,false,p->{try(Store s=new Store(f.c,f.database)){assertEquals(TrackingDelay.Phase.CLAIMED,p.phase);id.set(s.begin());effects.incrementAndGet();j.finish(p.token,TrackingDelay.Phase.STARTED,id.get(),"");}first.countDown();},error->{throw new AssertionError(error);});assertTrue(first.await(10,TimeUnit.SECONDS));f.idle();CountDownLatch second=new CountDownLatch(1);j.claim("due",elapsed+1,1,false,p->{assertNull("Duplicate durable claim must not authorize another capture",p);second.countDown();},error->{throw new AssertionError(error);});assertTrue(second.await(10,TimeUnit.SECONDS));assertEquals(1,effects.get());assertEquals(id.get(),new TrackingDelaySettings(f.factory.open(f.c)).read().session);try(Store s=new Store(f.c,f.database)){assertEquals(1,s.rows("SELECT * FROM sessions").size());long actual=s.rows("SELECT start FROM sessions").get(0).getLong("start");assertTrue(actual>=wall);assertTrue(actual>=plan.wall+300000);assertTrue(s.rows("SELECT * FROM epochs").isEmpty());assertTrue(s.rows("SELECT * FROM clips").isEmpty());}}}
 @Test public void cancellationAndStaleFinishCannotOverwriteReplacement()throws Exception{try(TrackingDelayFixture f=new TrackingDelayFixture()){f.arm("old");TrackingDelay p=f.store().read();f.job().finish(p.token,TrackingDelay.Phase.CANCELLED,0,"");f.idle();assertEquals(TrackingDelay.Phase.CANCELLED,f.store().read().phase);f.arm("new");f.job().finish("old",TrackingDelay.Phase.INTERRUPTED,0,"stale");f.idle();assertEquals("new",f.store().read().token);assertEquals(TrackingDelay.Phase.WAITING,f.store().read().phase);try(Store s=new Store(f.c,f.database)){assertTrue(s.rows("SELECT * FROM sessions").isEmpty());}}}
 @Test public void lostServiceAndRebootAreInterruptedWithoutCaptureOrReplay()throws Exception{try(TrackingDelayFixture f=new TrackingDelayFixture()){f.arm("lost");TrackingDelay p=f.store().read();f.job().claim(p.token,p.deadline,p.boot,false,null,null);f.idle();f.job().inspect(token->true,p.boot);f.idle();assertEquals("A live preparing admission retains its durable claim",TrackingDelay.Phase.CLAIMED,f.store().read().phase);f.job().inspect(token->false,p.boot);f.idle();assertEquals(TrackingDelay.Phase.INTERRUPTED,f.store().read().phase);f.arm("reboot");p=f.store().read();f.job().inspect(token->true,p.boot+1);f.idle();assertEquals(TrackingDelay.Phase.INTERRUPTED,f.store().read().phase);try(Store s=new Store(f.c,f.database)){assertTrue(s.rows("SELECT * FROM sessions").isEmpty());}}}
 @Test public void malformedJournalIsHonestAndDoesNotClearEvidence()throws Exception{try(TrackingDelayFixture f=new TrackingDelayFixture()){assertTrue(f.factory.open(f.c).edit().putString("token","bad").commit());f.job().inspect(token->false,0);f.idle();assertTrue(f.job().state.error.contains("unreadable"));assertEquals("bad",f.factory.open(f.c).getString("token",""));assertEquals(0,f.starts);}}
}
